          "concept_titles": [
            {
              "en": "Reading network interface settings",
              "fr": "Lire la configuration d'une interface réseau"
            }
          ]
        },
        {
          "title": {
            "en": "Checking connectivity",
            "fr": "Vérifier la connectivité"
