          "summary": {
            "en": "Test reachability between devices using command-line tools, and interpret the results including latency and packet loss.",
            "fr": "Testez l'accessibilité entre des appareils à l'aide d'outils en ligne de commande, et interprétez les résultats incluant la latence et la perte de paquets."
          },
          "concept_titles": [
            {
              "en": "Checking connectivity",
              "fr": "Vérifier la connectivité"
            }
          ]
        },
        {
          "title": {
            "en": "Inspecting the routing table",
            "fr": "Inspecter la table de routage"
          },
          "summary": {
            "en": "Read the routing table from the command line to understand how the system decides which gateway to use when sending packets to different destinations.",
            "fr": "Lisez la table de routage en ligne de commande pour comprendre comment le système décide quelle passerelle utiliser lors de l'envoi de paquets vers différentes destinations."
          },
          "concept_titles": [
            {
              "en": "Inspecting the routing table",
              "fr": "Inspecter la table de routage"
            }
          ]
        },
        {
          "title": {
            "en": "Querying DNS from the command line",
            "fr": "Interroger DNS en ligne de commande"
          },
          "summary": {
            "en": "Use command-line tools to perform DNS lookups, resolve a hostname to an IP address, and troubleshoot name resolution problems.",
            "fr": "Utilisez des outils en ligne de commande pour effectuer des recherches DNS, résoudre un nom d'hôte en adresse IP, et diagnostiquer des problèmes de résolution de noms."
          },
          "concept_titles": [
            {
              "en": "Querying DNS from the command line",
              "fr": "Interroger DNS en ligne de commande"
            }
          ]
        },
        {
          "title": {
            "en": "Introduction to firewalls",
            "fr": "Introduction aux pare-feux"
          },
          "summary": {
            "en": "Learn what a firewall does, how it filters traffic by IP address, port and protocol, and how to view basic firewall rules from the command line.",
            "fr": "Découvrez ce que fait un pare-feu, comment il filtre le trafic par adresse IP, port et protocole, et comment afficher des règles de pare-feu de base en ligne de commande."
          },
          "concept_titles": [
            {
              "en": "Introduction to firewalls",
              "fr": "Introduction aux pare-feux"
            }
          ]
        }
      ]
    }
  ]
}
